import { RealtimeServer } from "./src/server.ts";
import { LoopbackTransport, joinMessage } from "./src/transport.ts";
import { VoiceSession } from "./src/session.ts";
import { encode, PROTOCOL_VERSION } from "./src/protocol.ts";

const events = [];
const replied = [];
const transcripts = [];
const server = new RealtimeServer({
  tokens: new Set(["valid"]),
  budgetSeconds: 0.2,
  telemetry: event => events.push(event),
  respond: transcript => { transcripts.push(transcript); return `reply:${transcript}`; },
});

assert.deepEqual(joinMessage("room", "valid"), { type: "join", roomId: "room", token: "valid", version: PROTOCOL_VERSION });
server.handle("bad", encode({ type: "join", roomId: "room", token: "nope", version: PROTOCOL_VERSION }), raw => replied.push(JSON.parse(raw)));
assert.equal(replied.pop().reason, "auth");
server.handle("old", encode({ type: "join", roomId: "room", token: "valid", version: 1 }), raw => replied.push(JSON.parse(raw)));
assert.equal(replied.pop().reason, "version");

const session = new VoiceSession(new LoopbackTransport(server, "c1"));
session.start("room", "valid");
assert.equal(session.state, "ready");
assert.ok(session.sessionId?.startsWith("s"));
session.pressTalk();
const first = session.sessionId + ".t1";
assert.equal(session.state, "listening");
session.audio(0.1, "secret ");
session.audio(0.05, "text");
session.releaseTalk();
assert.equal(session.state, "speaking");
assert.equal(session.lastResponse, "reply:secret text");
session.pressTalk();
assert.equal(session.state, "listening");
assert.ok(events.some(event => event.name === "cancelled" && event.correlationId === first));
const firstAudio = events.find(event => event.name === "audio");
assert.equal(firstAudio.ms, 100);
assert.equal(Object.prototype.hasOwnProperty.call(firstAudio, "transcript"), false);

session.audio(0.05, "next");
session.releaseTalk();
assert.equal(session.state, "speaking");
session.finishSpeaking();
assert.equal(session.state, "ready");
session.pressTalk();
session.audio(0.001, "over");
assert.equal(session.state, "ended");
assert.equal(session.endReason, "budget");

let reentrantServer;
const raceReplies = [];
reentrantServer = new RealtimeServer({
  tokens: new Set(["valid"]),
  budgetSeconds: 120,
  telemetry: () => {},
  respond: () => {
    reentrantServer.handle("race", encode({ type: "cancel", correlationId: "cid" }), () => {});
    return "stale";
  },
});
reentrantServer.handle("race", encode({ type: "join", roomId: "r", token: "valid", version: PROTOCOL_VERSION }), () => {});
reentrantServer.handle("race", encode({ type: "ptt", correlationId: "cid", pressed: true }), () => {});
reentrantServer.handle("race", encode({ type: "audio", correlationId: "cid", ms: 1, transcript: "x" }), () => {});
reentrantServer.handle("race", encode({ type: "ptt", correlationId: "cid", pressed: false }), raw => raceReplies.push(JSON.parse(raw)));
assert.equal(raceReplies.length, 0);

