// Layer 3 (media transport): in-process loopback link between a client session and the server.
import { decodeServer, encode, PROTOCOL_VERSION } from "./protocol.ts";
import type { ClientMessage, ServerMessage } from "./protocol.ts";
import type { RealtimeServer } from "./server.ts";

export function joinMessage(roomId: string, token: string): ClientMessage {
  return { type: "join", roomId, token, version: PROTOCOL_VERSION };
}

export class LoopbackTransport {
  private readonly server: RealtimeServer;
  private readonly connection: string;
  private listener: (message: ServerMessage) => void = () => {};

  constructor(server: RealtimeServer, connection: string) {
    this.server = server;
    this.connection = connection;
  }

  onMessage(listener: (message: ServerMessage) => void): void {
    this.listener = listener;
  }

  send(message: ClientMessage): void {
    this.server.handle(this.connection, encode(message), (raw) => {
      const decoded = decodeServer(raw);
      if (decoded !== null) this.listener(decoded);
    });
  }
}

// Layer 2 (orchestration): push-to-talk client session state machine.
import { correlation } from "./protocol.ts";
import type { ServerMessage } from "./protocol.ts";
import { joinMessage } from "./transport.ts";
import type { LoopbackTransport } from "./transport.ts";

export type SessionState = "idle" | "joining" | "ready" | "listening" | "thinking" | "speaking" | "ended";

export class VoiceSession {
  state: SessionState = "idle";
  sessionId: string | null = null;
  lastResponse: string | null = null;
  endReason: string | null = null;
  private turn = 0;
  private current: string | null = null;
  private usedMs = 0;
  private readonly transport: LoopbackTransport;

  constructor(transport: LoopbackTransport) {
    this.transport = transport;
    transport.onMessage((message) => this.onServer(message));
  }

  start(roomId: string, token: string): void {
    this.state = "joining";
    this.transport.send(joinMessage(roomId, token));
  }

  /** Push-to-talk pressed. While the assistant is speaking this is a barge-in. */
  pressTalk(): void {
    if (this.state === "speaking" && this.current !== null) {
      this.transport.send({ type: "cancel", correlationId: this.current });
    } else if (this.state !== "ready") {
      return;
    }

    if (this.sessionId === null) return;
    this.turn += 1;
    this.current = correlation(this.sessionId, this.turn);
    this.state = "listening";
    this.transport.send({ type: "ptt", correlationId: this.current, pressed: true });
  }

  /** Microphone chunk; `seconds` is the chunk duration reported by the capture layer. */
  audio(seconds: number, transcript: string): void {
    if (this.state !== "listening" || this.current === null) return;
    const ms = seconds * 1000;
    if (!Number.isFinite(ms) || ms < 0) return;
    this.usedMs += ms;
    this.transport.send({ type: "audio", correlationId: this.current, ms, transcript });
  }

  releaseTalk(): void {
    if (this.state !== "listening" || this.current === null) return;
    this.state = "thinking";
    this.transport.send({ type: "ptt", correlationId: this.current, pressed: false });
  }

  finishSpeaking(): void {
    if (this.state === "speaking") this.state = "ready";
  }

  private onServer(message: ServerMessage): void {
    if (message.type === "joined") {
      this.sessionId = message.sessionId;
      this.state = "ready";
    } else if (message.type === "rejected") {
      this.state = "ended";
      this.endReason = message.reason;
    } else if (message.type === "ended") {
      this.state = "ended";
      this.endReason = message.reason;
    } else if (message.type === "response" && message.correlationId === this.current && this.state === "thinking") {
      this.lastResponse = message.text;
      this.state = "speaking";
    }
  }
}

// Layer 4 (server boundary): authenticates joins, meters audio, answers turns.
import { decodeClient, encode, PROTOCOL_VERSION } from "./protocol.ts";
import type { ClientMessage, ServerMessage, TelemetryEvent } from "./protocol.ts";

export interface ServerOptions {
  tokens: ReadonlySet<string>;
  budgetSeconds: number;
  telemetry: (event: TelemetryEvent) => void;
  respond: (transcript: string) => string;
}

interface Session {
  id: string;
  usedMs: number;
  transcript: string;
  active: string | null;
  pending: string | null;
  ended: boolean;
}

export class RealtimeServer {
  private readonly options: ServerOptions;
  private readonly sessions = new Map<string, Session>();
  private count = 0;

  constructor(options: ServerOptions) {
    this.options = options;
  }

  /** Handle one raw client frame for `connection`; replies go to `reply`. */
  handle(connection: string, raw: string, reply: (raw: string) => void): void {
    const send = (message: ServerMessage) => reply(encode(message));
    const message = decodeClient(raw);
    if (message === null) {
      send({ type: "rejected", reason: "malformed" });
      return;
    }
    if (message.type === "join") {
      this.sessions.delete(connection);
      this.join(connection, message, send);
      return;
    }

    const session = this.sessions.get(connection);
    if (!session || session.ended) {
      send({ type: "rejected", reason: "malformed" });
      return;
    }

    if (message.type === "audio") {
      if (!validCorrelation(message.correlationId) || session.active !== message.correlationId ||
          !finiteNonnegative(message.ms) || typeof message.transcript !== "string") {
        send({ type: "rejected", reason: "malformed" });
        return;
      }
      session.usedMs += message.ms;
      session.transcript += message.transcript;
      this.options.telemetry({
        name: "audio",
        sessionId: session.id,
        correlationId: message.correlationId,
        ms: message.ms,
      });
      if (session.usedMs > this.options.budgetSeconds * 1000) {
        session.ended = true;
        this.options.telemetry({ name: "budget_exhausted", sessionId: session.id, ms: session.usedMs });
        this.sessions.delete(connection);
        send({ type: "ended", reason: "budget" });
      }
    } else if (message.type === "ptt") {
      if (!validCorrelation(message.correlationId) || typeof message.pressed !== "boolean") {
        send({ type: "rejected", reason: "malformed" });
        return;
      }
      if (message.pressed) {
        session.active = message.correlationId;
        session.transcript = "";
      } else if (session.active === message.correlationId) {
        session.pending = message.correlationId;
        const text = this.options.respond(session.transcript);
        if (session.pending === message.correlationId) {
          this.options.telemetry({ name: "response", sessionId: session.id, correlationId: message.correlationId });
          send({ type: "response", correlationId: message.correlationId, text });
        }
      }
    } else if (message.type === "cancel") {
      if (!validCorrelation(message.correlationId)) {
        send({ type: "rejected", reason: "malformed" });
        return;
      }
      this.options.telemetry({ name: "cancelled", sessionId: session.id, correlationId: message.correlationId });
      if (session.pending === message.correlationId) session.pending = null;
      if (session.active === message.correlationId) session.active = null;
    }
  }

  private join(connection: string, message: Extract<ClientMessage, { type: "join" }>,
               send: (message: ServerMessage) => void): void {
    if (!Number.isInteger(message.version)) {
      send({ type: "rejected", reason: "malformed" });
      return;
    }
    if (message.version !== PROTOCOL_VERSION) {
      send({ type: "rejected", reason: "version" });
      return;
    }
    if (typeof message.roomId !== "string" || message.roomId.length === 0 ||
        typeof message.token !== "string" || !this.options.tokens.has(message.token)) {
      send({ type: "rejected", reason: "auth" });
      return;
    }
    this.count += 1;
    const id = `s${this.count}`;
    this.sessions.set(connection, {
      id,
      usedMs: 0,
      transcript: "",
      active: null,
      pending: null,
      ended: false,
    });
    this.options.telemetry({ name: "joined", sessionId: id });
    send({ type: "joined", sessionId: id });
  }
}

function validCorrelation(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function finiteNonnegative(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value) && value >= 0;
}

